// Normalizar el body (n8n puede entregar los datos en .body o en la raíz)
const raw = $input.first().json.body ?? $input.first().json;

const {
  taskId,
  title        = 'Sin título',
  description  = '',
  dueDate      = '',
  assignedDate = '',
  userEmail    = '',
} = raw;

if (!taskId) throw new Error('taskId es obligatorio en el payload del backend');

const prompt = [
  'Eres un asistente académico universitario. Analiza la siguiente tarea y devuelve ÚNICAMENTE un objeto JSON sin markdown ni texto extra.',
  '',
  'TAREA:',
  `Título: ${title}`,
  `Descripción: ${description || 'Sin descripción'}`,
  `Fecha de entrega: ${dueDate}`,
  '',
  'Formato de respuesta (solo JSON):',
  '{',
  '  "subjectName": "nombre completo de la asignatura universitaria más probable, o DESCONOCIDA si no puedes determinarlo",',
  '  "taskType": "uno de: ESSAY, CODE_SNIPPET, UML_DIAGRAM, PRESENTATION, READING, EXAM, OTHER",',
  '  "content": "solución completa y detallada en formato Markdown en español"',
  '}',
].join('\n');

return [{ json: { taskId, userEmail, title, prompt } }];

// Parsear la respuesta de Gemini y combinar con datos anteriores
const geminiResponse = $input.first().json;
const prevData = $('Construir Prompt para Gemini').first().json;

let parsed = {};
try {
  const rawText = geminiResponse?.candidates?.[0]?.content?.parts?.[0]?.text ?? '{}';
  // Gemini a veces envuelve en ```json ... ``` aunque se pida sin markdown
  const cleaned = rawText.replace(/```json\n?/g, '').replace(/```/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = {
    subjectName: 'DESCONOCIDA',
    taskType: 'OTHER',
    content: `Error al parsear respuesta de Gemini: ${e.message}`,
  };
}

const allowedTypes = ['ESSAY','CODE_SNIPPET','UML_DIAGRAM','PRESENTATION','READING','EXAM','OTHER'];
const taskType = allowedTypes.includes(parsed.taskType) ? parsed.taskType : 'OTHER';

return [{
  json: {
    taskId:      prevData.taskId,
    userEmail:   prevData.userEmail,
    subjectName: parsed.subjectName || 'DESCONOCIDA',
    taskType,
    content:     parsed.content || 'Solución no disponible.',
  }
}];
